WITH enriched AS (SELECT src.*, b.product_name FROM inventory src LEFT JOIN products b ON src.product_id = b.id WHERE ARRAY_CONTAINS(b.tags, 'bestseller')) SELECT DATE_TRUNC('QUARTER', last_restock) AS quarter_start, DATE_TRUNC('MONTH', last_restock) AS activity_month, ROUND(AVG(quantity), 2) AS avg_quantity, STDDEV_SAMP(quantity) AS quantity_stddev, BIT_AND(quantity) AS quantity_bit_and, COUNT(DISTINCT store_id) AS distinct_store_ids, PERCENTILE_APPROX(quantity, 0.5) AS quantity_p50, GROUPING_ID() AS grouping_level FROM enriched GROUP BY ROLLUP (DATE_TRUNC('QUARTER', last_restock), DATE_TRUNC('MONTH', last_restock))
